// GENERATED by "npm run kit" from kit/lang.js at the repo root. Do not edit this copy: change kit/lang.js and run npm run kit.
// Pure: no DOM. Language rules shared by every part (K-6, D-12). A part keeps its own texts and builds its i18n from
// them: export const { LANGS, DEFAULT_LANG, t, setLang, getLang, normalizeLang, pickLang } = createI18n(STRINGS);
// kit/langdom.js is the browser half (?lang=, the saved choice, data-i18n attributes, the language switch).

// 'Best: {n}' + { n: 5 } → 'Best: 5'. A placeholder without a value is left as written.
export const interpolate = (s, vars) => (vars ? String(s).replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m)) : s);

// strings: { en: { key: 'text' }, sv: { ... } }. The first language is the default: it is what a missing key falls
// back to, and what the language is until setLang() is called (so Node tests see it).
// One current language for the whole part, so pure modules can call t() without a language being passed around.
export function createI18n(strings) {
  const LANGS = Object.keys(strings);
  const DEFAULT_LANG = LANGS[0];
  let current = DEFAULT_LANG;

  // 'sv-SE' → 'sv'; unsupported or empty → null.
  function normalizeLang(code) {
    const base = String(code ?? '').trim().toLowerCase().split(/[-_]/)[0];
    return LANGS.includes(base) ? base : null;
  }

  // ?lang= (the launcher passes it) wins, then the saved choice, then the browser's languages, then the default.
  function pickLang({ query = null, saved = null, browser = [] } = {}) {
    for (const code of [query, saved, ...(browser || [])]) {
      const lang = normalizeLang(code);
      if (lang) return lang;
    }
    return DEFAULT_LANG;
  }

  const getLang = () => current;
  function setLang(lang) { current = normalizeLang(lang) || DEFAULT_LANG; return current; }

  // t('best', { n: 5 }). A key missing in the language falls back to the default language, then to the key itself.
  const t = (key, vars, lang = current) => interpolate(strings[lang]?.[key] ?? strings[DEFAULT_LANG][key] ?? key, vars);

  return { LANGS, DEFAULT_LANG, normalizeLang, pickLang, getLang, setLang, t };
}

// ----- checks for a part's own tests -----

const placeholders = (s) => [...new Set(String(s).match(/\{\w+\}/g) || [])].sort().join(' ');

// What is wrong with a table of texts (empty list = fine): every language has the default language's keys and no
// others, no text is empty, and a translation uses the same {placeholders} as the original.
export function stringProblems(strings) {
  const [base, ...others] = Object.keys(strings);
  const problems = [];
  for (const [key, text] of Object.entries(strings[base])) {
    if (typeof text !== 'string' || !text.trim()) problems.push(`${base}.${key} is empty`);
  }
  for (const lang of others) {
    for (const key of Object.keys(strings[base])) {
      const text = strings[lang][key];
      if (text === undefined) problems.push(`${lang}.${key} is missing`);
      else if (typeof text !== 'string' || !text.trim()) problems.push(`${lang}.${key} is empty`);
      else if (placeholders(text) !== placeholders(strings[base][key])) problems.push(`${lang}.${key} has other placeholders than ${base}.${key}`);
    }
    for (const key of Object.keys(strings[lang])) if (!(key in strings[base])) problems.push(`${lang}.${key} has no ${base} text`);
  }
  return problems;
}

// The keys a page asks for through data-i18n, data-i18n-html, data-i18n-aria and data-i18n-title, without repeats.
export function htmlKeys(html) {
  return [...new Set([...String(html).matchAll(/\bdata-i18n(?:-html|-aria|-title)?\s*=\s*(["'])(.*?)\1/g)].map((m) => m[2]))];
}

// The keys a page asks for that the table (its default language) does not have.
export const missingHtmlKeys = (html, strings) => htmlKeys(html).filter((key) => !(key in strings[Object.keys(strings)[0]]));
